# One combined image change on the Z5 CSV: the 20-byte zone read at
# 0x60a8f708 becomes a getter call of key 0x99a1. The hook answers it.
# Do not edit this file after it has run.
import csv
from pathlib import Path

ROOT = Path('.')
Z5 = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes-c1.csv'
OUT = ROOT / 'work/out/overlay-changed-bytes.csv'
DIFF = ROOT / 'work/out/overlay-profile-diff-t6.txt'
BASE = 0x60A8F708
NEW = bytes.fromhex('fccca199000089fcdc00000000dd6b3c5dffc00c')
PURPOSE = 'EMULATOR-ONLY profile read: builder calls getter 0x99a1. Role: behaviour.'


def main():
    with Z5.open(encoding='utf-8', newline='') as f:
        reader = csv.DictReader(f)
        fields = reader.fieldnames
        rows = list(reader)
    changed = []
    by_addr = {}
    for rec in rows:
        addr = int(rec['runtime_address'], 16)
        by_addr[addr] = rec
    if len(NEW) != 20:
        raise SystemExit('new window is not 20 bytes')
    for i, b in enumerate(NEW):
        addr = BASE + i
        rec = by_addr.get(addr)
        if rec is None:
            raise SystemExit(f'Z5 has no row at {addr:#x}')
        old = int(rec['proposed_byte'], 16)
        if old != b:
            changed.append((addr, old, b, rec['source'], rec['section']))
            rec['proposed_byte'] = f'{b:02x}'
            rec['source'] = 'profile-read'
            rec['purpose'] = PURPOSE
    lines = [f'rows {len(rows)} replaced {len(changed)}']
    for addr, old, new, source, section in changed:
        lines.append(f'{addr:#x} {old:02x} -> {new:02x} was {source} section {section}')
    # Call at 0x60a8f715: dd disp32, target must be 0x60063380.
    call = BASE + 13
    disp = int.from_bytes(NEW[14:18], 'little', signed=True)
    target = (call + disp) & 0xFFFFFFFF
    lines.append(f'call {call:#x} disp {disp:#x} target {target:#x}')
    if target != 0x60063380:
        raise SystemExit('getter target moved')
    text = '\n'.join(lines) + '\n'
    DIFF.write_text(text, encoding='utf-8')
    with OUT.open('w', encoding='utf-8', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=fields, lineterminator='\n')
        writer.writeheader()
        writer.writerows(rows)
    print(text, end='')


if __name__ == '__main__':
    main()
